css:
:root, :root[data-theme], [data-theme] {
  --bg-app: rgba(3, 20, 42, .54) !important;
  --bg-chrome: rgba(3, 20, 42, .54) !important;
  --bg-editor: rgba(3, 20, 42, .54) !important;
  --bg-elevated: rgba(3, 20, 42, .54) !important;
  --bg-hover: rgba(35, 72, 112, .36) !important;
  --bg-active: rgba(47, 103, 151, .46) !important;
  --bg-input: rgba(3, 20, 42, .54) !important;
  --bg-panel: rgba(3, 20, 42, .54) !important;
  --bg-sidebar: rgba(3, 20, 42, .54) !important;
  --bg-status: rgba(3, 20, 42, .54) !important;
  --border: rgba(109, 176, 229, .22) !important;
  --border-strong: rgba(127, 201, 255, .36) !important;
}
html, body {
  min-height: 100%;
  background-color: #040816 !important;
}
body {
  background-image: linear-gradient(rgba(2, 7, 19, .16), rgba(2, 7, 19, .31)), url("data:image/jpeg;base64,") !important;
  background-position: center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}
#root, [class*="start" i], [class*="workspace" i] {
  background-color: transparent !important;
}
header, aside, main, nav, footer, [role="dialog"] {
  background-color: rgba(3, 20, 42, .54) !important;
  backdrop-filter: blur(16px) saturate(135%) !important;
  -webkit-backdrop-filter: blur(16px) saturate(135%) !important;
}
aside {
  border-right-color: rgba(3, 20, 42, .54) !important;
  box-shadow: 2px 0 0 rgba(3, 20, 42, .54) !important;
}
[class*="splitter" i], [class*="resizer" i], [class*="resize-handle" i] {
  background-color: rgba(3, 20, 42, .54) !important;
  border-color: rgba(3, 20, 42, .54) !important;
}
.monaco-editor, .monaco-editor-background, .monaco-editor .margin, .monaco-editor .overflow-guard {
  background-color: transparent !important;
}
